from pathlib import Path
import json, sqlite3, sys
CID='MANUAL-SCOUT-HENGELTJES-20260924'
root=Path.home()/'prediction_research_prod'/'knowledge'/'codex_runtime'
label=sys.argv[1] if len(sys.argv)>1 else 'snapshot'
print('HENGELTJE_AUTOBUILD_PHASE='+label)
hits=[]
for p in (root/'candidate_states').glob('*.json'):
    try:x=json.loads(p.read_text())
    except Exception:continue
    if x.get('candidate_id')==CID:hits.append((p.stat().st_mtime,p,x))
if not hits:
    print('HENGELTJE_OVERLAY=ABSENT')
else:
    _,p,x=max(hits)
    print('HENGELTJE_OVERLAY='+str(p))
    print('HENGELTJE_QUEUE_STATUS='+str(x.get('queue_status')))
    print('HENGELTJE_SCIENTIFIC_STATUS='+str(x.get('scientific_status') or x.get('economic_conclusion') or 'NO_PROVEN_EDGE'))
    print('HENGELTJE_BUILD_HANDOFF='+str(bool(x.get('build_handoff'))))
    print('HENGELTJE_RUNTIME_HEALTH='+str(x.get('runtime_health')))
    print('HENGELTJE_PROSPECTIVE_OUTCOME='+str(x.get('prospective_outcome') or x.get('prospective_status')))
try:
    db=sqlite3.connect(f"file:{root/'runtime.sqlite'}?mode=ro",uri=True)
    rows=db.execute('select id,body,status,attempt from tasks order by rowid').fetchall()
    db.close()
except Exception as exc:
    print('HENGELTJE_RUNTIME_DB='+type(exc).__name__)
else:
    ts=[]
    for tid,body,status,attempt in rows:
        try:b=json.loads(body)
        except Exception:continue
        if b.get('candidate_id')==CID:ts.append((tid,b,status,attempt))
    print('HENGELTJE_TASK_COUNT='+str(len(ts)))
    for tid,b,status,attempt in ts[-12:]:
        print('HENGELTJE_TASK='+tid+' status='+status+' attempt='+str(attempt)+' class='+str(b.get('task_class'))+' planner='+str(bool(b.get('candidate_build_planner')))+' builder='+str(bool(b.get('candidate_builder') or b.get('sol_builder'))))
print('NO_LIVE_TRADING=YES')
print('NO_PAID_ACTIONS=YES')
print('NO_WALLET_ACTIONS=YES')
print('NO_REMOTE_PUSH=YES')
